#include <vector>

class Solution {
public:
    bool canArrange(std::vector<int>& arr, int k) {
        std::vector<int> rem(k, 0);
        for (int x : arr) {
            rem[((x % k) + k) % k]++;
        }
        if (rem[0] % 2 != 0) return false;
        for (int i = 1; i < k; ++i) {
            if (rem[i] != rem[k - i]) return false;
        }
        return true;
    }
};

class Solution {
    public boolean canArrange(int[] arr, int k) {
        int[] rem = new int[k];
        for (int x : arr) {
            rem[((x % k) + k) % k]++;
        }
        if (rem[0] % 2 != 0) return false;
        for (int i = 1; i < k; i++) {
            if (rem[i] != rem[k - i]) return false;
        }
        return true;
    }
}

var canArrange = function(arr, k) {
    const rem = new Array(k).fill(0);
    for (const x of arr) {
        rem[((x % k) + k) % k]++;
    }
    if (rem[0] % 2 !== 0) return false;
    for (let i = 1; i < k; i++) {
